def p(*xs):return ''.join('<p>'+x+'</p>' for x in xs)
def table(head,rows):return '<div class="table-wrap" tabindex="0"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def note(title,text):return '<aside class="callout"><strong>'+title+'</strong><p>'+text+'</p></aside>'
def code(x):return '<pre><code>'+escape(x)+'</code></pre>'

def chapter(page,lang):
    t=lambda en,zh:zh if lang=='zh' else en
    rows=[]
    def add(ident,title,intro,body,refs=(),viz=None):rows.append((ident,title,intro,body,refs,viz))
    if page=='foundations':
        add('scope',t('Open sources become intelligence through analysis','公开来源经过分析才形成情报'),t('Start with a question that a reader can evaluate.','从读者能够评估的问题开始。'),p(t('OSINT is the collection and analysis of openly obtainable information to answer a defined question. A pile of search results is information; a supported conclusion explains what the sources establish, what they cannot establish, and why it matters to the question. Open-source intelligence is unrelated to whether a software repository is open source.','OSINT 是采集与分析公开可获取的信息，以回答明确问题。检索结果堆积是信息；有依据的结论应解释来源能证明什么、不能证明什么，以及与问题的关系。开源情报与软件仓库是否开放源码没有直接关系。'),t('A useful starting question is “Does this image show the public bridge named in its caption?” Separate that from “Who took it?” and “What happened there?” The same picture may support the first question while leaving the others unresolved.','好的起点是“这张图是否展示说明中提到的公共桥梁？”应与“谁拍摄？”、“那里发生了什么？”分开。一张图可能支持第一个问题，却无法回答其余问题。')),('berkeley',),'cycle')
        add('plan',t('A small collection plan prevents aimless browsing','小型采集计划能避免漫无目的浏览'),t('Define the decision, scope, information gaps and stopping condition.','明确判断目标、范围、信息缺口与停止条件。'),table([t('Field','字段'),t('Example','示例')],[(t('Question','问题'),t('Which of three public landmarks matches the scene?','三个公共地标中哪个匹配场景？')),(t('Inputs & scope','输入与范围'),t('Original image, claimed city, public map imagery; no personal identity investigation','原图、所称城市、公开地图影像；不涉及个人身份调查')),(t('Needed evidence','所需证据'),t('Road–river topology, building shape, independently captured street imagery','道路与河流拓扑、建筑轮廓、独立拍摄街景')),(t('Stop / revise','停止 / 修订'),t('Stop at a documented match or state an unresolved region; widen the scope only after testing the claim','记录匹配后停止，或报告未解决区域；检验原主张后再扩大范围'))])+p(t('Keep an evidence ledger while you search. Record unsuccessful queries and rejected candidates too: they make it possible to resume a case and show that the favorite answer was actually tested.','边搜索边维护证据台账。失败查询与被排除候选也应记录：既方便恢复工作，也能说明最喜欢的答案确实接受过检验。')),('guides',))
        add('branches',t('The major branches share an evidence discipline','主要方向共享证据分析方法'),t('Choose a branch by the question, rather than collecting every tool.','按问题选择方向，而不是收集所有工具。'),table([t('Direction','方向'),t('Typical question','典型问题'),t('Frequent mistake','常见错误')],[(t('GEO / chronolocation','地理 / 时间定位'),t('Where and when could this scene exist?','场景可能在何地、何时存在？'),t('Recognizing a country but claiming an exact camera point','识别国家后直接声称精确拍摄点')),(t('Media verification','媒体核验'),t('Is this a reused image, an edit or a new claim?','是否旧图重用、编辑产物或新主张？'),t('A detector score is treated as proof','把检测分数当作证明')),(t('Organizations & infrastructure','组织与基础设施'),t('What documented relationship connects these entities?','实体间有何可记录关系？'),t('Same name or IP is treated as the same owner','同名或同 IP 被当作同一所有者')),(t('Events & public records','事件与公开记录'),t('What is the supported timeline?','有依据的时间线是什么？'),t('Upload, event and archive times are conflated','混淆上传、事件及归档时间'))]),('toolkit',))
    elif page=='collection':
        add('queries',t('Search is an experiment with explicit inputs','检索是具有明确输入的实验'),t('Translate an information gap into several query families.','将信息缺口转成多个查询族。'),p(t('Search exact phrases, spelling variants, local-language names and historical names. Narrow by a publisher or file type when useful. Save the query, engine, filters and retrieval time. Search indexing, personalization and regional access affect what appears.','检索精确短语、拼写变体、本地语言名称及历史名称。必要时按发布者或文件类型缩小范围。保存查询、引擎、过滤条件及检索时间；索引、个性化与地区访问条件影响结果。'),t('For a public landmark, try its local name with “bridge”, “opening”, “renovation” or the local equivalents. Read the source page instead of citing only a snippet. Search snippets and AI summaries can be truncated or outdated.','查询公共地标时，将本地名称与“桥梁”、“启用”、“修缮”等当地对应词组合。应阅读来源页面，而非只引用摘要；搜索摘要及 AI 概要可能截断或过时。'))+code('"public landmark name" renovation\nsite:official-publisher.example bridge\n"local-language name" filetype:pdf')+p(t('The .example publisher above is illustrative, not a real target. Keep the broad query if a narrow one returns nothing: lack of indexed results does not establish absence.','上面的 .example 发布者仅作演示，并非真实目标。窄查询无结果时保留宽查询；缺乏索引结果不能证明不存在。')),('search',))
        add('lineage',t('Trace the publication chain before counting sources','统计来源数量前先追踪发布链'),t('Ten reposts may contain just one observation.','十次转发可能只有一次观察。'),p(t('Find the earliest accessible version, examine quoted links, compare crops and watermarks, and identify which publisher actually observed the scene. The earliest indexed copy is only the earliest you found; it may not be the original. Preserve alternate versions with their own IDs.','寻找最早可访问版本，检查引用链接、裁剪与水印，识别谁实际观察过场景。最早索引副本只是你找到的最早版本，未必是原件。不同版本应分别编号保存。'),t('Treat sources as independent only for the claim they independently support. An official road map may independently support geometry but say nothing about the time of an event. An article embedding the same video is not another camera.','来源独立性要针对具体主张判断。官方道路地图可独立支持几何关系，却不一定说明事件时间。嵌入同一视频的报道不是另一台相机。')),('berkeley','archive'),'lineage')
        add('bounded',t('Collect what the question needs','采集问题真正需要的内容'),t('Distinguish public research from interactions that change the environment.','区分公开检索与会改变环境的交互。'),p(t('Public documents, map queries and registration lookups answer many questions without contacting a subject. Login, messages, friend requests and scanning are different operations with different authorization requirements. Plan them separately rather than quietly broadening a collection task.','公开文档、地图查询及注册信息检索足以回答许多问题，无需联系调查对象。登录、发消息、好友请求及扫描是另一类操作，授权要求不同；应单独规划，不应悄悄扩大采集任务。'),t('Prefer small, reproducible queries and official export/API routes. Record pagination, sampling and missing fields. An API or platform limit can cause a partial dataset; a clean graph may still omit most of the network.','优先采用小范围可复现查询与官方导出 / API 路径。记录分页、抽样及缺失字段；API 或平台限制会产生不完整数据，即使图表整洁也可能遗漏大部分网络。')),('nominatim-policy','toolkit'))
    elif page=='media':
        add('copies',t('Reverse image search answers reuse questions','反向搜图主要回答重用问题'),t('Search both the whole image and distinctive crops.','同时检索整张图与具有辨识度的局部。'),p(t('Lens and TinEye can surface similar or indexed copies. Compare uncropped edges, resolution, visible signs and accompanying text. A match with an older caption is a lead: read the older page and verify whether its scene and date are actually supported.','Lens 与 TinEye 可发现相似图或已索引副本。比较未裁剪边缘、分辨率、可见标牌及说明文字。带更早说明的匹配是线索；应打开旧页面，核验其场景与日期是否有依据。'),t('A missing match does not prove authenticity. Cropping, mirroring, new uploads and limited indexes can hide copies. If upload to an external service is inappropriate for the material, use local inspection and textual clue searches instead.','无匹配不能证明真实。裁剪、镜像、新上传及有限索引都可能隐藏副本。若素材不适合上传外部服务，可采用本地检查与文字线索检索。')),('lens','tineye'))
        add('frames',t('Inspect a video as a sequence, not a single thumbnail','把视频当作序列检查，而不只是缩略图'),t('Track continuity, camera motion and keyframe timestamps.','跟踪连续性、相机运动及关键帧时间码。'),p(t('Select frames where signs, roads and distant structures become clear. Keep each frame’s timestamp and a link to the source video. Motion can reveal whether a landmark is behind another object or whether two cuts represent different locations. Audio may provide leads, but captions and voiceovers can be added later.','选择标牌、道路及远处结构清晰的帧，保留每帧时间码与原视频链接。运动可揭示遮挡顺序，或显示剪辑前后是否属于不同地点。音频可提供线索，但字幕及配音可能后加。'),t('InVID helps organize verification tasks; Hugin can combine overlapping frames for scene inspection. A panorama is a derived image with warping and possibly moving objects. Keep raw frames beside the panorama so the transformation remains visible.','InVID 可组织核验任务；Hugin 能将重叠帧合成全景辅助观察。全景属于衍生图，存在形变或移动物体；原始帧应与全景一起保存，使转换过程可见。')),('invid','hugin'),'media')
        add('metadata',t('Metadata is a clue with a provenance problem','元数据是需要溯源的线索'),t('Inspect the original bytes before making copies or edits.','复制与编辑前检查原始字节。'),p(t('ExifTool can read embedded camera, GPS and time fields. Preserve its output alongside the original file. EXIF time may lack a time zone, GPS can be absent or edited, and a filesystem modification time may describe download rather than capture. Messaging platforms often strip metadata.','ExifTool 可读取相机、GPS 及时间字段。将输出与原件一起保存。EXIF 时间可能没有时区，GPS 可能缺失或被修改，文件修改时间可能代表下载而非拍摄；消息平台常移除元数据。'),t('Compression artifacts, inconsistent lighting and generative-image detectors can prompt further checks, but none alone establishes fabrication. Verify the source chain and physical scene; keep “not verified” distinct from “fake”.','压缩痕迹、光照不一致及生成图检测器可提示进一步检查，但任何一项都不能单独证明伪造。应核验来源链与物理场景，并区分“尚未核验”与“虚假”。'))+code('exiftool -G1 -a -s original.jpg'),('exiftool','berkeley'))
    elif page=='entities':
        add('identity',t('Resolve entities before drawing relationships','绘制关系前先辨清实体'),t('Names are labels; identifiers and dated records support identity.','名称是标签；标识符与有日期记录支持身份判断。'),p(t('For an organization, compare jurisdiction, registration number, official domains and historical names. For public accounts, a similar handle is only a candidate. Store the exact record and date of each relation: “listed as director in filing X” is more precise than “controls company Y”.','分析组织时，比较司法辖区、注册号、官方域名及历史名称。相似公开账号名只是候选。记录关系的精确出处与日期：“在文件 X 中列为董事”比“控制公司 Y”更准确。'),t('Official registries are valuable anchors but may be delayed, self-reported or limited to one jurisdiction. Do not merge entities just because their names or profile pictures match. Separate identity confidence from confidence in a specific claimed relationship.','官方登记是有用的锚点，但可能延迟、由当事人申报或仅覆盖一个辖区。不能因同名或同头像就合并实体；实体身份置信度与某项关系置信度应分别表达。')),('companies','guides'))
        add('domains',t('Infrastructure evidence supports narrow claims','基础设施证据支持的是有限主张'),t('Different records describe different layers and dates.','不同记录描述不同层次及日期。'),table([t('Source','来源'),t('Can support','可能支持'),t('Cannot establish alone','单独不能确定')],[(t('Registration / RDAP','注册信息 / RDAP'),t('Public registrar and registration fields returned at lookup time','查询时返回的公开注册商及注册字段'),t('The real-world operator behind redacted data','隐藏字段后的现实运营者')),(t('DNS record','DNS 记录'),t('A resolution observed at a specified time','指定时刻观察到的解析'),t('Ownership from shared hosting or a CDN IP','通过共享主机或 CDN IP 判断所有权')),(t('CT certificate log','CT 证书日志'),t('A logged certificate contains specified names','已记录证书包含某些名称'),t('Current service, compromise or common ownership','当前服务状态、入侵或共同所有者'))])+p(t('Lookups to published data sources are not an active test of the underlying server. Keep observation time, response and query method. Historical names may be retired; wildcard certificates do not enumerate every actual host.','查询已发布数据源并不是对目标服务器的主动测试。保留观察时间、响应与查询方法；历史名称可能已停用，通配符证书也不会枚举全部实际主机。')),('icann','ct','crt'),'entities')
        add('graph',t('Use a sourced graph to expose gaps','用有出处的关系图揭示空缺'),t('Every edge needs a type, date and evidence ID.','每条边都应具有类型、日期及证据编号。'),p(t('Model nodes as distinct entities and edges as claims such as “publishes”, “registered in” or “appears in filing”. Attach the underlying source and confidence to each edge. A shared address can be a service provider; a visual cluster can be created by your layout algorithm.','将节点建模为独立实体，边建模为“发布”、“注册于”、“出现在文件中”等主张。每条边附来源与置信度。共享地址可能属于服务机构，视觉聚类可能只是布局算法的产物。'),t('Gephi is useful for exploration and presentation, but calculate metrics only after examining coverage and duplicates. Show unresolved identities separately. A reproducible small graph is often more useful than a dramatic chart with thousands of unsupported edges.','Gephi 可辅助探索与展示，但计算指标前应检查覆盖与重复。未确定身份应单列；可复现的小图往往比几千条无依据边组成的巨大图更有价值。')),('gephi',))
    elif page=='evidence':
        add('ledger',t('Separate the original, observation and inference','分开原件、观察与推断'),t('A future reader should be able to retrace each claim.','后来的读者应能追踪每项主张。'),table([t('Record','记录'),t('Keep','保留内容')],[(t('Source ID','来源编号'),t('Stable internal ID, URL, publisher and accessible version','稳定内部编号、URL、发布者及可访问版本')),(t('Acquisition','采集'),t('UTC retrieval time, method, response context and collector notes','UTC 检索时间、方法、响应上下文及采集笔记')),(t('File','文件'),t('Original filename, byte hash, format and a separate derived-copy path','原文件名、字节哈希、格式及独立衍生副本路径')),(t('Claim','主张'),t('Exact observation, inference, alternatives and supporting / contradicting IDs','具体观察、推断、替代解释及支持 / 反驳编号')),(t('Presentation','展示'),t('Necessary crop/redaction, transformation log and source attribution','必要裁剪 / 脱敏、转换记录及来源署名'))])+p(t('An archive, screenshot and downloaded file serve different roles. A screenshot records visible rendering; it may omit full text or metadata. An archived page can fail to load a video. Verify that the saved artifact actually preserves the fact you plan to cite.','归档、截图及下载文件作用不同。截图记录可见渲染，可能遗漏全文或元数据；存档页面可能无法加载视频。应核验保存产物确实保留了准备引用的事实。')),('berkeley','webrecorder'),'evidence')
        add('hash',t('Hashing detects changed bytes, not a false caption','哈希能发现字节改变，不能识别错误说明'),t('Integrity and authenticity are different properties.','完整性与真实性是不同属性。'),p(t('Compute a SHA-256 digest when acquiring an original. Recompute it before later analysis to check whether the saved bytes changed. Keep transformed copies under new names and link them to their input. Identical hashes mean identical bytes; they do not prove the scene, creator, date or caption.','获取原件时计算 SHA-256，之后分析前重新计算以检查保存字节是否变化。转换副本用新名称，并关联其输入。哈希相同意味着字节相同，不证明场景、作者、日期或说明。'))+code('python3 -c "import hashlib,pathlib; print(hashlib.sha256(pathlib.Path(\'original.jpg\').read_bytes()).hexdigest())"')+p(t('Record handling steps. If the original platform has already recompressed a file, describe it as the platform-served copy rather than the camera original. A chain-of-custody log makes handling auditable but does not automatically settle legal admissibility.','记录处理步骤。若平台已重新压缩文件，应称为平台提供副本，而非相机原件。保管链日志有助于审计，但不会自动解决法律上的可采性。')),('berkeley',))
        add('archive',t('Preserve the context, then test replay','保存上下文，再测试回放'),t('A saved URL is a pointer, not a preserved source.','保存 URL 是留下指针，不是保存来源。'),p(t('Use Wayback to look for available historical captures and Webrecorder-style browser archiving where appropriate. Save visible attribution, capture time and the original URL. Reopen the result: dynamic maps, embedded media and authenticated resources may not replay completely.','可用 Wayback 查找已有历史快照，适当时采用 Webrecorder 类浏览归档。保存可见署名、采集时间及原始 URL，并重新打开测试；动态地图、嵌入媒体及登录资源可能无法完整回放。'),t('Keep a private working archive and a deliberately selected public report. Remove session credentials and irrelevant personal details from public artifacts. Preserve the necessary geographic context around a match instead of cropping every screenshot to an isolated roof.','工作归档与经过选择的公开报告应分开。公开产物移除会话凭据与无关个人细节。地点匹配截图应保留必要周边地理上下文，不要只裁出一块孤立屋顶。')),('archive','webrecorder'))
    elif page=='geo':
        add('pipeline',t('Location is a hypothesis to test','地点是需要检验的假设'),t('Move from broad constraints to a small candidate set.','从宽泛约束走向小型候选集。'),p(t('Begin with an observation sheet: visible roads, buildings, terrain, text and camera direction. Separate what is visibly present from interpretations such as “probably a school”. Use claimed region or language as a search bound, not a fact that must be true.','先建立观察表：可见道路、建筑、地形、文字及镜头方向。将确实可见的内容与“可能是学校”等解释分开。所称区域或语言是搜索边界，不是必须成立的事实。'),t('Generate several candidates using combinations of rare, stable features. Verify each with spatial relationships, then seek a different view or source. Start with exact geometry before polishing an address. If only a region is supported, report the region and the unresolved detail.','用少见且稳定的要素组合生成多个候选，逐个核验空间关系，再寻找不同视角或来源。先确认几何关系，再完善地址；若仅支持区域，应报告区域与未解决细节。')),('guides','osm-search'),'geo')
        add('scale',t('Region, scene and camera point are different results','区域、场景及拍摄点是不同结果'),t('Report at the resolution supported by the evidence.','按证据支持的精度报告。'),table([t('Level','层次'),t('What is established','确定了什么'),t('What remains','尚未确定')],[(t('Region','区域'),t('Several broad clues narrow the search area','多条宏观线索限定搜索区域'),t('Specific site and viewpoint','具体地点及视点')),(t('Scene / landmark','场景 / 地标'),t('Roads, water and structures match one site','道路、水体及结构匹配某一地点'),t('Exact side, elevation and camera position','精确侧面、高度与相机位置')),(t('Viewpoint','视点'),t('Bearings, occlusion and perspective fit a position or short segment','方位、遮挡及透视匹配某一点或短区间'),t('Exact coordinate precision and capture time','精确坐标精度及拍摄时间'))])+p(t('Image location, camera location and depicted subject can differ. A telephoto image may show a landmark far from the camera; a street panorama may have a displaced marker. Give a radius, segment or visible uncertainty when appropriate.','画面地点、相机地点与被拍对象位置可能不同。长焦图可展示远离相机的地标；街景标记也可能偏移。必要时给出半径、区间或明确不确定性。')),('maps','earth'))
        add('reject',t('Try to break the preferred candidate','尝试推翻最喜欢的候选'),t('A hard spatial contradiction can outweigh many weak similarities.','强空间矛盾可能胜过许多弱相似。'),p(t('Compare intersection order, which bank a building occupies, bridge alignment, rail curvature and the skyline behind the camera-facing side. A roof color may be common; a required river on the wrong side is a stronger contradiction. Before rejecting, check image mirroring, camera orientation and whether the map is from a different year.','比较路口顺序、建筑所在河岸、桥梁方向、铁路弯曲及面对镜头一侧的背景天际线。屋顶颜色可能普遍，而必须出现的河流在错误一侧属于较强矛盾。排除前检查图像镜像、相机朝向及地图年代。'),t('Maintain “matches / contradicts / unverified” for every candidate. Lack of Street View is unverified, not a contradiction. Stop when the remaining result is sufficiently supported for your original question; do not manufacture certainty just because the search was long.','每个候选按“匹配 / 矛盾 / 未核验”记录。缺少街景属于未核验，不属于矛盾。剩余结果足够回答原问题时停止，不要因搜索耗时很长而制造确定性。')),('guides',))
    elif page=='visual':
        add('clues',t('Prefer stable geometry over a single memorable detail','优先稳定几何，不依赖单个显眼细节'),t('Record broad clues, then search for distinctive combinations.','记录宏观线索，再寻找独特组合。'),table([t('Clue family','线索类别'),t('What to record','记录什么'),t('Confounder','干扰因素')],[(t('Roads','道路'),t('Lane count, intersection topology, medians, rail crossings','车道数、路口拓扑、中央隔离及铁路交叉'),t('Resurfacing, construction, mirrored images','重铺、施工、镜像图')),(t('Buildings','建筑'),t('Footprint, roofline, orientation and spacing','轮廓、屋顶线、朝向与间距'),t('Renovation, demolition, perspective distortion','修缮、拆除、透视形变')),(t('Text & signs','文字与标牌'),t('Exact visible characters, script, route numbers','确实可见字符、文字体系、道路编号'),t('Blur, OCR mistakes, copied branding','模糊、OCR 错误、相同品牌')),(t('Landscape','景观'),t('Water bends, hills, coastline and vegetation pattern','河曲、山丘、海岸及植被分布'),t('Season, drought, imported vegetation','季节、干旱、引入植物')),(t('Street furniture','街道设施'),t('Pole shapes, traffic lights, barriers and drain patterns','杆件形态、信号灯、护栏与排水形态'),t('Common suppliers and regional overlap','共同供应商与区域重叠'))]),('guides',),'clues')
        add('topology',t('Read the scene as a graph of relationships','将场景读成关系图'),t('“Across from” is often more useful than “looks similar”.','“位于对岸”往往比“看起来相似”更有用。'),p(t('Describe relations that survive viewpoint changes: a road crosses a river before reaching a T-junction; a long building lies between rail and water; a tower is behind the bridge from the camera. Turn these into a sketch before searching a map.','描述能跨视角保留的关系：道路越过河流后到达丁字路口；长建筑位于铁路与水体之间；从相机看塔在桥后方。查询地图前先画成示意图。'),t('Distances in a photograph are perspective-dependent. A near object may dominate the image while a distant skyline is compressed. Use relative order and occlusion first; estimate distances only when the scene has a usable scale or a calibrated viewpoint.','照片内距离受透视影响。近物可能占据画面，远处天际线可能压缩。先用相对顺序与遮挡；只有可用尺度或经校准视点时才估算距离。')),('osm-search','qgis'))
        add('text',t('Transcribe uncertainty instead of inventing letters','记录文字不确定性，不补造字符'),t('A partial sign can be searched without pretending it is complete.','不完整标牌也可检索，无需假装已读全。'),p(t('Write clear characters literally and mark unreadable segments, such as “BRI[?]GE”. Compare alternate alphabets and local transliterations. Use OCR as a suggestion and retain the original crop. A chain logo may narrow a country but seldom uniquely identifies a branch.','清晰字符照录，不可读部分明确标记，例如“BRI[?]GE”。比较其他文字体系与本地音译。OCR 作为建议，原始裁剪应保留。连锁标志可能缩小国家范围，却很少能唯一确定门店。'),t('Clothing, vegetation and architecture are probabilistic clues, not national identifiers. Ask how widely a feature occurs and whether another independent feature supports the same region. Do not let a confident language guess override a contradictory coastline.','服饰、植被与建筑是概率性线索，并非国家标识。应考虑要素分布范围及是否有另一独立线索支持同一区域。不能用自信的语言猜测覆盖矛盾的海岸线。')),('guides','toolkit'))
    elif page=='maps':
        add('views',t('Use map products for different kinds of evidence','将不同地图产品用于不同证据'),t('A labeled map, satellite image and street panorama are not interchangeable.','标注地图、卫星图与街景全景不能互相替代。'),table([t('View','视图'),t('Best use','主要用途'),t('Check','核对')],[(t('Labeled road / POI map','道路 / POI 标注地图'),t('Names, route structure and administrative context','名称、路网结构与行政背景'),t('Pin placement and naming source','图钉位置与名称来源')),(t('Pure overhead imagery','纯俯视影像'),t('Footprints, water, road geometry and surrounding context','轮廓、水体、道路几何与周边上下文'),t('Date, north orientation, stitching and labels turned off','日期、北向、拼接及关闭标签')),(t('Street panorama','街景全景'),t('Ground signs, facade, occlusion and camera-side match','地面标牌、立面、遮挡与拍摄侧匹配'),t('Capture date, panorama origin, camera marker and orientation','拍摄时间、全景来源、相机标记与朝向')),(t('3D view','三维视图'),t('Terrain and broad perspective comparison','地形与整体透视比较'),t('Model artifacts and mixed-date textures','模型伪影与混合日期纹理'))]),('maps','streetview','earth-date'),'maps')
        add('query',t('Search OpenStreetMap by relationships','按关系查询 OpenStreetMap'),t('Query a small region, then inspect the surrounding geometry.','查询小区域，再检查周边几何。'),p(t('Bellingcat OSM Search can find combinations of mapped features. Overpass Turbo allows more explicit queries. Nominatim resolves names and addresses; it is not an image-geolocation engine. A missing mapped feature may simply be unmapped.','Bellingcat OSM Search 可查找地图要素组合，Overpass Turbo 支持更明确的查询。Nominatim 解析名称与地址，不是图片定位引擎。查不到要素可能只是尚未被绘制。'))+code('[out:json][timeout:25];\n(\n  way["bridge"]({{bbox}});\n  way["railway"="rail"]({{bbox}});\n);\nout geom;')+p(t('Paste this teaching query into Overpass Turbo after zooming to a small area. It returns bridge-tagged ways and rail ways; it does not itself prove they are close together, that every bridge is mapped, or that any site matches an image. Compare the geometry and refine the query.','在 Overpass Turbo 缩放到小范围后粘贴教学查询。它返回带桥标签的 way 与铁路 way，并不证明两者相邻、桥梁全部已绘制或地点匹配图片。仍需比较几何并进一步细化。')),('overpass','osm-search','nominatim','nominatim-policy'))
        add('regional',t('Use regional maps without mixing their coordinates','使用本地地图时不要混用坐标'),t('Provider coverage and local names can be better than a single global map.','本地覆盖与名称可能比单一全球地图更适合。'),p(t('For mainland China, compare AMap or Baidu naming with available street imagery and overhead geometry. Keep a labeled view for names and a separate pure-imagery view for geometry. Road/POI overlays may not align with the underlying imagery in another product. Verify with recognizable intersections rather than shifting everything by an assumed offset.','中国大陆可比较高德、百度的本地名称、可用街景及俯视几何。名称保留标注图，几何另留纯影像图。道路 / POI 叠加层在其他产品中可能与底图不对齐；应以可识别路口核验，而非按假定偏移整体移动。'),t('If one service is blocked, use a different original provider for the required evidence type. Mapillary and KartaView can supply community ground images where covered, but coverage and account requirements vary. Absence on a second site is not evidence that the place does not exist.','某服务无法访问时，可选择提供同类证据的另一原始服务。Mapillary 与 KartaView 在有覆盖处可提供社区地面图，但覆盖及账号条件不同。另一站没有结果不证明地点不存在。')),('amap','baidu','amap-coord','mapillary','kartaview'))
    elif page=='imagery':
        add('resolution',t('Choose the sensor for the size of the question','按问题尺度选择传感器'),t('Zooming enlarges pixels; it does not add captured detail.','放大像元不会增加已采集细节。'),p(t('Sentinel-2 optical bands have nominal 10, 20 or 60 metre spatial sampling. They are useful for land cover and sufficiently large changes, not reading small signs or identifying people. NASA Worldview layers vary widely in resolution and cadence; broad smoke or flood patterns are a better fit than a single doorway.','Sentinel-2 光学波段名义空间采样为 10、20 或 60 米，适合地表覆盖及足够大的变化，不适合读取小标牌或识别人。NASA Worldview 图层的分辨率与更新周期差异很大，广域烟雾或洪水比单扇门更适合。'),t('RGB rendering is a chosen interpretation of bands. False-color and radar products can reveal different properties, but require different reasoning. Do not apply the same color assumptions to optical and radar imagery, or confuse pixel spacing with guaranteed object recognition.','RGB 渲染是波段组合的选择。假彩色及雷达产品能显示不同性质，但解释方法不同。不能把光学与雷达影像套用同一颜色含义，也不能将像元间距等同于可靠物体识别。')),('sentinel','worldview'),'imagery')
        add('dates',t('Capture date, mosaic date and access date differ','拍摄日期、拼接日期与访问日期不同'),t('Record which date the product actually exposes.','记录产品实际提供的是哪种日期。'),p(t('Google Earth imagery can be assembled from images acquired on different dates; 3D textures also need careful interpretation. A historical timeline label is not a guarantee of one exact capture instant for every pixel. Read the displayed imagery metadata and retain the area around the evidence.','Google Earth 影像可能由不同日期采集图像拼接而成，三维纹理也需谨慎解释。历史时间轴标签不保证每个像元对应同一精确采集时刻。应阅读显示的影像元数据，并保留证据周边区域。'),t('In Copernicus Browser or EarthExplorer, save the scene/product identifier, acquisition time, band selection and cloud information. A platform upload time or the date printed in a news caption is a separate claim. Clouds can hide a feature, so “not visible” is not always “absent”.','在 Copernicus Browser 或 EarthExplorer 中保存场景 / 产品标识、采集时间、波段组合及云信息。平台上传时间与报道说明日期是另一项主张。云可能遮住要素，因此“不可见”不总等于“不存在”。')),('earth-date','copernicus-doc','earthexplorer'))
        add('change',t('Compare like with like before claiming a change','声称发生变化前先进行可比对照'),t('Season, clouds, sensor and viewing angle can explain differences.','季节、云层、传感器及视角都能解释差异。'),p(t('Use a before/after pair with comparable resolution, band combination, location and season where possible. Inspect shadows, water levels and vegetation. Align recognizable stable structures and document any reprojection or resampling. Keep original products beside your annotated comparison.','尽量选取分辨率、波段组合、位置及季节可比的前后图。检查阴影、水位与植被；对齐可识别稳定结构，记录重投影或重采样。原产品应与标注对照一起保存。'),t('For a large new roof, report when it was first observed and the interval between the last clear absence and first clear presence. That bounds the visible change; it does not automatically give the construction start date or cause.','对大型新增屋顶，可报告首次观察时间，以及最后一次清晰未出现与首次清晰出现之间的区间。这限制了可见变化时间，但不会自动确定开工时间或原因。')),('copernicus-doc','earth-history','qgis'))
    elif page=='terrain':
        add('horizon',t('A skyline is a sequence of relative shapes','天际线是相对轮廓的序列'),t('Match peak order, saddles and apparent height ratios.','匹配山峰顺序、鞍部及视高度比例。'),p(t('Trace the horizon separately from foreground buildings and clouds. Compare a sequence of peaks and valleys, not one triangular hill. Apparent heights depend on distance and camera elevation; a closer low ridge may hide a taller distant peak.','将地平线与前景建筑及云层分开描摹。比较峰谷序列，不只一座三角山。视高度依距离与相机高程而变；较近低山可能挡住更远高峰。'),t('PeakVisor and terrain views can suggest candidates. In QGIS, combine elevation data, bearing and a plausible viewpoint. Retain several candidate ridges until the relative profile and surrounding roads agree. A named peak label is a lead, not proof.','PeakVisor 与地形视图可提供候选。QGIS 可结合高程、方位及合理视点。相对轮廓与周边道路一致前，应保留多个候选山脊。山峰名称只是线索，不是证明。')),('peakvisor','dem','qgis'),'terrain')
        add('viewshed',t('Visibility is a constraint with assumptions','可见性是依赖假设的约束'),t('A DEM, observer height and target height define a simplified model.','DEM、观察者高度及目标高度组成简化模型。'),p(t('A terrain line-of-sight test asks whether modeled ground blocks a target. Add observer height relative to the data surface and account for the target’s height. Buildings and vegetation may be missing or represented differently. A visible target in a model may still be obscured in the photograph.','地形视线检验询问模型地面是否遮挡目标。应加入相对数据表面的观察者高度，考虑目标高度。建筑与植被可能缺失或采用不同表达；模型中可见的目标仍可能在照片中被遮挡。'),t('For distant horizons, curvature, refraction and vertical reference become relevant. Start with a rough compatibility test and state its assumptions; do not describe a low-resolution model as centimetre-accurate surveying.','远距离地平线还涉及地球曲率、折射及高程基准。先做粗略相容性检验并列出假设；不能将低分辨率模型描述为厘米级测绘。')),('dem','qgis'))
        add('failure',t('Check why a terrain match might be misleading','检查地形匹配为何可能误导'),t('The candidate should explain foreground and background together.','候选应同时解释前景与背景。'),p(t('Telephoto compression, a tilted camera and a mirrored image can distort a casual comparison. Lens distortion may change edges; a cropped frame can remove the most distinctive saddle. Inspect several frames or uncropped versions when available.','长焦压缩、相机倾斜及镜像会影响直觉比较。镜头畸变可能改变边缘，裁剪可能去掉最有辨识度的鞍部。可用时检查多帧或未裁剪版本。'),t('A good terrain candidate also fits the road direction, water position and camera-side occlusion. If the skyline agrees but the only plausible access road is on the wrong side, keep the contradiction rather than dismissing it as a small detail.','好的地形候选还应匹配道路方向、水体位置及拍摄侧遮挡。若天际线吻合，但唯一合理道路在错误一侧，应保留该矛盾，而不是当作小细节忽略。')),('guides','peakvisor'))
    elif page=='time':
        add('timeline',t('Build time bounds before estimating an exact moment','估算精确时刻前先建立时间边界'),t('Different timestamps describe different events.','不同时间戳描述不同事件。'),table([t('Timestamp','时间戳'),t('Meaning','含义'),t('Caution','注意')],[(t('Capture / event','拍摄 / 事件'),t('When the depicted scene was recorded or occurred','场景被记录或事件发生时'),t('Metadata and captions need verification','元数据及说明需核验')),(t('Upload / publication','上传 / 发布'),t('When a platform or publisher made a copy available','平台或发布者提供某份副本时'),t('May be much later than the scene','可能远晚于画面时间')),(t('Archive capture','归档采集'),t('When an archive recorded an accessible response','归档记录可访问响应时'),t('Not necessarily the first publication','不一定是首次发布')),(t('Research retrieval','研究检索'),t('When you obtained the evidence','你获取证据时'),t('Only describes your acquisition','只描述你的采集'))])+p(t('A completed building, road closure or festival banner can supply a time bound if its own dated record is reliable. State “after X, before Y” when that is what the evidence supports; do not turn a broad interval into a single date.','已完工建筑、道路封闭或节庆横幅可提供时间界限，前提是相关日期记录可靠。证据只支持区间时，应表述“X 之后、Y 之前”，不能缩成某一天。')),('archive','earth-date'),'time')
        add('sun',t('Shadows test compatibility with a solar position','阴影用于检验太阳位置相容性'),t('Establish true north and the shadow’s physical plane first.','先确定真北及阴影所在物理平面。'),p(t('For a vertical object on level ground, the shadow points away from the solar azimuth. If the sun’s azimuth is A, the shadow bearing is approximately (A + 180°) mod 360°. In the same ideal model, shadow length is h / tan(α), where h is object height and α solar elevation. These are not direct formulas for arbitrary photo pixels.','水平地面上的竖直物体，其阴影指向太阳方位反方向。太阳方位为 A 时，阴影方位约为 (A + 180°) mod 360°。同一理想模型中，阴影长度为 h / tan(α)，h 为物体高度，α 为太阳高度角。这些公式不能直接套在任意照片像素上。'),t('SunCalc lets you compare a location, date and time. Check time zone, daylight saving and azimuth convention. Slope, nonvertical objects, occlusion and perspective change what the image shows. Record a range of plausible dates/times rather than a falsely exact answer.','SunCalc 可比较地点、日期与时间。核对时区、夏令时及方位约定。坡度、非竖直物体、遮挡与透视会改变图中表现。应记录合理日期 / 时间范围，避免虚假的精确答案。')),('suncalc','noaa'))
        add('ambiguity',t('A matching shadow is rarely a unique timestamp','匹配阴影很少对应唯一时间戳'),t('Several dates and locations may yield similar geometry.','多个日期及地点可能产生相近几何。'),p(t('Solar paths repeat seasonally, and a single bearing leaves many unknowns. Combine shadow evidence with a known location, independent time bounds and several trustworthy observations. Weather and vegetation are supporting context with geographic and seasonal overlap.','太阳路径具有季节性重复，单一方位仍留下很多未知量。阴影证据应与已知地点、独立时间边界及多项可靠观察结合。天气与植被只是具有地理及季节重叠的辅助背景。'),t('NOAA’s legacy solar calculator is no longer actively maintained; its documentation is useful for calculation assumptions. Cross-check current ephemeris tools instead of treating one calculator output as certified evidence. If no independent bounds exist, leave the time question unresolved.','NOAA 旧太阳计算器已停止主动维护，其文档可用于理解计算假设。应交叉检查现有星历工具，不能把单个输出当作认证证据。若没有独立时间界限，应保留时间问题未解决。')),('noaa','suncalc'))
    elif page=='coordinates':
        add('format',t('A coordinate needs order, units and a reference','坐标需要顺序、单位及参考体系'),t('Two numbers without labels are an incomplete location record.','没有标签的两个数并不是完整地点记录。'),p(t('Decimal latitude ranges from −90 to 90; longitude from −180 to 180. North/east are conventionally positive in signed decimal degrees. DMS uses degrees, minutes and seconds; apply the hemisphere sign to the complete value. More decimal places show numeric precision, not verified accuracy.','十进制度纬度范围为 −90 至 90，经度为 −180 至 180。带符号十进制度中通常北 / 东为正。DMS 使用度、分、秒，半球符号应应用于整个数值。更多小数位只表明数值精度，不表明已核验准确度。'),t('Interfaces differ: many map searches accept latitude, longitude; GeoJSON positions use longitude, latitude. A swap can be invalid, or both numbers can remain valid while pointing somewhere entirely different. Read the format contract and label fields explicitly.','界面约定不同：许多地图搜索接受纬度、经度；GeoJSON 位置使用经度、纬度。交换后可能越界，也可能两个数都有效却指向完全不同地点。应阅读格式约定并明确字段标签。'))+code('{"type":"Point","coordinates":[120.0,30.0]}'),('geojson','qgis-crs'),'coordinates')
        add('crs',t('Assigning a CRS and transforming coordinates are different','指定 CRS 与转换坐标是不同操作'),t('First determine what the source numbers mean.','先确定源数值含义。'),p(t('WGS 84 geographic coordinates, projected Web Mercator metres and local projected coordinates use different models and units. QGIS can reproject correctly identified layers. Assigning EPSG:4326 to a metre-based file only changes the interpretation label; it does not magically convert the numbers.','WGS 84 地理坐标、Web Mercator 投影米制坐标及本地投影坐标使用不同模型和单位。QGIS 能重投影标识正确的图层。给米制文件指定 EPSG:4326 只是改变解释标签，不会自动转换数值。'),t('GCJ-02 used by mainland-China mapping services and Baidu’s BD-09 need provider-aware handling. Do not overlay their raw numbers on a WGS 84 image and assume alignment. Consult provider documentation, keep the original system label and verify transformed results against multiple stable intersections.','中国大陆地图服务使用的 GCJ-02 及百度 BD-09 需要按服务约定处理。不能将原始数值叠加 WGS 84 影像后假定已对齐。查阅提供商文档，保留原体系标签，并以多个稳定路口核验转换结果。')),('qgis-crs','amap-coord','baidu'))
        add('measure',t('Measure with an uncertainty appropriate to the data','按数据支持的不确定性测量'),t('A map pin, camera marker and survey control point have different reliability.','地图图钉、相机标记与测量控制点可靠性不同。'),p(t('Use a geodesic distance for geographic coordinates rather than treating degree differences as metres. Projected measurements also depend on projection distortion. For small comparisons, a clearly labeled rough distance may suffice; for exact surveying, use a suitable reference, method and calibrated data.','地理坐标应采用测地距离，不要把度数差当成米。投影测量也依赖投影畸变。小范围比较中明确标注的粗略距离可能足够；精确测绘则需要适当参考、方法及校准数据。'),t('A POI search can return a building centroid, entrance or district point. A georeferenced scan may fit selected ground-control points while drifting elsewhere. Check independent points and retain residuals and method notes. Report a viewpoint segment or area when the evidence does not justify one pin.','POI 搜索可能返回建筑质心、入口或行政区代表点。配准扫描图可能在所选控制点吻合、其他地方漂移。应检查独立点，保留残差与方法笔记。证据不支持单图钉时，应报告视点区间或区域。')),('nominatim','qgis-georef','qgis'))
    elif page=='analysis':
        add('matrix',t('Compare hypotheses claim by claim','逐项主张比较假设'),t('Use a matrix to see contradictions and missing checks.','用矩阵显示矛盾与缺少的核验。'),p(t('List candidate hypotheses in columns and observations in rows. Mark whether each observation matches, contradicts or remains unverified. Give strong geometric contradictions explicit attention. Do not invent a numeric probability by adding arbitrary points to every clue.','候选假设放在列，观察放在行，标记匹配、矛盾或未核验。强几何矛盾应明确突出。不能给每条线索随意打分相加后声称获得数值概率。'),t('Ask what would look different if the preferred explanation were wrong. Seek that disconfirming evidence and retain plausible alternatives. Several clues may come from the same image or underlying map dataset, so they are not automatically independent confirmations.','询问首选解释若错误，会出现什么不同现象；寻找这些反证并保留合理替代解释。多条线索可能来自同一图片或底层地图数据，不能自动视为独立确认。')),('guides','berkeley'),'analysis')
        add('confidence',t('Describe confidence with its reasons and limits','用原因及局限解释置信度'),t('Confidence is a judgment, not a substitute for evidence.','置信度是判断，不是证据替代品。'),p(t('For this course, use “strongly supported” when multiple distinctive spatial relations fit, there is independent corroboration and important contradictions have been checked. Use “plausible” when meaningful features fit but decisive checks are missing. Use “unresolved” when alternatives remain. These are reporting conventions, not calibrated probabilities.','本课程中，当多项独特空间关系吻合、存在独立佐证且重要矛盾已检查时，可用“充分支持”；有明显匹配但缺少决定性核验时用“合理候选”；替代解释仍存在时用“未解决”。这些是报告约定，并非校准概率。'),t('A confident place match may coexist with unknown time or creator. State confidence separately for each claim. Include what would change the conclusion, such as a dated uncropped frame or a ground view from the correct side.','高置信地点匹配可以同时存在时间或作者未知。应逐项主张表述置信度，并说明哪些新增证据会改变结论，例如有日期的未裁剪帧或正确侧面的地面视图。')),('berkeley',))
        add('report',t('Make the conclusion reviewable','让结论可审查'),t('A reader should see the claim, method, evidence and remaining uncertainty.','读者应看见主张、方法、证据及剩余不确定性。'),p(t('Lead with the supported answer and its scope. Follow with annotated comparisons retaining enough surrounding context, numbered sources, rejected alternatives and the method needed to reproduce the checks. Distinguish source statements from your own inferences.','先给出有依据的答案及范围，再附保留足够上下文的标注对照、来源编号、被排除替代解释及可复现核验方法。将来源陈述与你的推断分开。'),t('A useful deliverable can say “The public landmark is identified; the camera lies somewhere along the marked road segment; the capture date remains unknown.” This is more informative than a precise coordinate and date with no supporting chain.','有用产出可以是“公共地标已识别；相机位于标注道路区间内；拍摄日期未知”。这比没有证据链的精确坐标与日期更有信息价值。')),('guides','berkeley'))
    elif page=='ai':
        add('assist',t('Use AI to organize leads and comparisons','用 AI 组织线索与对照'),t('Keep its contribution visible and checkable.','让其贡献可见且可核验。'),p(t('AI can suggest query variants, transcribe visible text, translate a sign, group an evidence ledger or draft an alternative-hypothesis table. Give it the allowed sources and ask for separate observation, inference and uncertainty fields. Verify transcripts against the image and citations against the actual page.','AI 可建议查询变体、转录可见文字、翻译标牌、整理证据台账或起草替代假设表。提供允许的来源，要求分别输出观察、推断及不确定性。转录按原图核验，引用按实际页面核验。'),t('A model’s landmark guess is a candidate generator, not another observation of the scene. Several models repeating the same location do not produce independent physical evidence. Keep the unedited model output if it affected the investigation, alongside corrections and human checks.','模型地标猜测是候选生成，不是场景的另一项观察。多个模型重复同一地点，不会产生独立物理证据。若输出影响调查，可保留未经编辑输出，并附纠正与人工核验。')),('guides','berkeley'),'ai')
        add('automation',t('Automate reversible processing, retain originals','自动化可逆处理，保留原件'),t('Small scripts are useful when inputs and transformations are clear.','输入与转换明确时，小型脚本很有用。'),p(t('Automate hashing, keyframe indexing, coordinate validation and formatting a source ledger. Log input IDs, parameters, tool versions and output paths. Keep original data outside the derived-output directory. Test a small sample before processing a large collection.','可自动化哈希、关键帧索引、坐标校验及台账格式化。记录输入编号、参数、工具版本及输出路径；原始数据与衍生产物目录分开。大批量处理前先测试小样本。'),t('Treat page text and documents as evidence, not executable instructions for an agent. An instruction embedded in a webpage to send data or log in is not authorization. Set collection boundaries and require review of externally visible actions.','将页面及文档内容视为证据，而非 Agent 的可执行指令。网页中要求发送数据或登录的文字不构成授权。应设定采集边界，对外部可见操作进行审查。')),('webrecorder','exiftool'))
        add('generated',t('Generated media changes verification, not the need for evidence','生成媒体改变核验方式，但证据仍必要'),t('Physical consistency and source lineage remain useful checks.','物理一致性与来源链仍是有效检查。'),p(t('Synthetic scenes can imitate regional signs and architecture. An impressive resemblance may be a composite of several places. Seek older independently captured views, coherent geometry across frames and a traceable publication chain. Preserve “no verified match found” rather than declaring a model guess correct.','合成场景能模仿区域标牌与建筑。高度相似画面可能是多个地点组合。应寻找更早独立拍摄视图、多帧一致几何及可追踪发布链。未找到可靠匹配时应保留结论，而非确认模型猜测。'),t('Use detector outputs as leads with known uncertainty, not verdicts. A genuine old photograph with a false caption can be just as misleading as a generated image. Validate each claim independently: scene, time, event and author.','检测输出应作为带不确定性的线索，而非裁决。真实旧照片配错误说明可能与生成图同样误导。场景、时间、事件及作者应分别核验。')),('berkeley','invid'))
    elif page=='practice':
        add('project-geo',t('Project 1 · Verify a public landmark','项目 1 · 核验公共地标'),t('Use your own photo or a clearly licensed public-landmark image.','使用自己拍摄或许可明确的公共地标图。'),p(t('Write an observation sheet before searching. Bound the region, generate at least three candidates, compare road–water–building relationships and reject alternatives with recorded reasons. Use a ground view and overhead view when both are available. Treat a missing view as an explicit gap.','检索前写观察表。限定区域，至少生成三个候选，比较道路、水体与建筑关系，记录排除理由。地面图与俯视图都可用时应同时使用；缺失视图应明确记为缺口。'),t('Deliver an annotated image, candidate matrix, source ledger and a location result with uncertainty. Do not begin with a known exact pin: choose a picture whose answer can later be independently checked. The synthetic bridge exercise in Labs is a quick preparation.','产出标注图、候选矩阵、来源台账及包含不确定性的地点结果。不要一开始就使用已知精确图钉；选择答案可在之后独立核验的图片。“互动练习”的合成桥梁案例可作为预习。')),('guides','osm-search'))
        add('project-change',t('Project 2 · Explain a visible land-cover change','项目 2 · 解释可见地表变化'),t('Choose a large feature suited to the available satellite resolution.','选择适合现有卫星分辨率的大型要素。'),p(t('Select a public reservoir, large construction site or broad vegetation area. Find comparable clear scenes before and after a visible change. Record product IDs, dates, band choices, cloud cover and alignment steps. Test seasonal or water-level explanations before calling the change permanent.','选择公共水库、大型施工区域或广域植被区。寻找变化前后可比的清晰场景。记录产品编号、日期、波段、云覆盖及对齐步骤。称为永久变化前先检验季节或水位解释。'),t('Deliver a side-by-side comparison, the earliest/latest observation bounds and a short explanation of what the sensor can establish. Keep causation and construction timing unresolved unless other independent records support them.','产出并列对照、最早 / 最晚观察界限及传感器能够证明什么的说明。若没有其他独立记录，原因与施工时间应保持未解决。')),('copernicus-doc','sentinel','worldview'))
        add('project-ledger',t('Project 3 · Reconstruct a public organization’s source trail','项目 3 · 重建公开组织的来源链'),t('Practice entity resolution without targeting a private individual.','练习实体辨识，不针对私人个体。'),p(t('Choose a public institution and one published claim about its own history or facilities. Trace official pages, accessible archived copies and registry records if applicable. Identify which publications reuse a common source and which independently support the claim.','选择公开机构及关于其自身历史或设施的一项已发布主张。追踪官方页面、可访问归档及适用登记记录。识别哪些发布复用了同一来源，哪些独立支持主张。'),t('Deliver a dated timeline, a small sourced relationship graph and a report separating observed records from interpretations. Use the downloadable case notebook for all three projects. The output is a reviewable investigation, not a leaderboard score or unsupported personal dossier.','产出有日期时间线、有出处的小型关系图及区分记录与解释的报告。三个项目均可使用下载的案例笔记模板。结果是可审查调查，而非排行榜分数或无依据个人档案。'))+p('<a href="case-notebook.md" download>'+t('Download the case notebook →','下载案例笔记模板 →')+'</a>'),('companies','archive','gephi'))
    return rows
